<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {usePhasePage} from '../phasePage'
import {explanationText,reviewExplanationCodes,type ReviewExplanation,type ReviewExplanationPage} from '../reviewExplanations'
import PhaseStatus from '../components/PhaseStatus.vue'
const {api,home,t,english,loading,busy,failure,notice,load,write}=usePhasePage(),items=ref<ReviewExplanation[]>([]),headOffice=ref(false)
const draft=ref<{id:string;expectedVersion:number;code:string;text:string;enabled:boolean}|null>(null),x=(key:Parameters<typeof explanationText>[0])=>explanationText(key,english())
function refresh(){if(!home.value?.employeeManage)return;void load(()=>api().get<ReviewExplanationPage>('/review-explanations'),p=>{items.value=p.items;headOffice.value=p.headOffice})}
function edit(item?:ReviewExplanation){if(!home.value?.headOffice||!headOffice.value)return;draft.value=item?{id:item.id,expectedVersion:item.version,code:item.code,text:item.text,enabled:item.enabled}:{id:crypto.randomUUID(),expectedVersion:0,code:'GENERAL',text:'',enabled:true}}
function save(){const d=draft.value;if(!d||!d.text.trim()||d.text.trim().length>500)return;void write(()=>api().put('/review-explanations/'+d.id,{expectedVersion:d.expectedVersion,code:d.code,text:d.text.trim(),enabled:d.enabled}),()=>{draft.value=null;refresh()})}
onMounted(refresh)
</script>
<template><section v-if="home?.employeeManage" class="wf-panel wf-form-panel"><header class="wf-toolbar"><h2>{{x('title')}}</h2><button v-if="home.headOffice&&headOffice" :disabled="loading||busy||items.length>=100" @click="edit()">{{x('add')}}</button></header><p class="wf-hint">{{x('hint')}}</p><p v-if="!home.headOffice" class="wf-hint">{{x('readonly')}}</p><PhaseStatus :loading="loading" :failure="failure" :notice="notice"/><form v-if="draft" class="wf-section" @submit.prevent="save"><h3>{{x(draft.expectedVersion?'edit':'new')}}</h3><fieldset :disabled="busy"><label>{{x('code')}}<select v-model="draft.code"><option v-for="code in reviewExplanationCodes" :key="code" :value="code">{{x(code)}}</option></select></label><label>{{x('text')}}<textarea v-model="draft.text" required maxlength="500" rows="3"></textarea></label><label class="wf-check"><input v-model="draft.enabled" type="checkbox">{{x('enabled')}}</label></fieldset><footer class="wf-form-actions"><button type="button" :disabled="busy" @click="draft=null">{{t('cancel')}}</button><button class="primary" :disabled="busy||!draft.text.trim()">{{t('save')}}</button></footer></form><section class="wf-section"><h3>{{x('saved')}} · {{items.length}}</h3><div class="wf-table-wrap"><table><thead><tr><th>{{x('code')}}</th><th>{{x('text')}}</th><th>{{t('status')}}</th><th/></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{x(item.code as typeof reviewExplanationCodes[number])}}</td><td>{{item.text}}</td><td>{{x(item.enabled?'enabled':'disabled')}}</td><td><button v-if="home.headOffice&&headOffice" :disabled="busy" @click="edit(item)">{{t('edit')}}</button></td></tr><tr v-if="!items.length"><td colspan="4">{{t('empty')}}</td></tr></tbody></table></div></section></section><p v-else role="alert">{{t('noAccess')}}</p></template>
